using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Runtime.CompilerServices;
using Hardlight;
using HardlightProject;
using NUnit.Framework;
using Unity.IL2CPP.CompilerServices;

namespace ProjectLucid.Tests
{
    // Behaviour specification for four HLAutoGenerated enum-string helpers and the
    // Enums comparer registry, written from the shipped x86-64 bodies:
    //   Hardlight.HardlightEnumExtensions      TypeDefIndex 8492, 0x060000a0..a9
    //   Hardlight.HardlightEnumExtentions      TypeDefIndex 8497, 0x060000b0..b2
    //   Enums.EnumComparers                    TypeDefIndex 8487, 0x06000097..98
    //   Enums.EnumExtentions                   TypeDefIndex 8488, 0x06000099..9a
    //   HardlightProject.HardlightEnumExtentions TypeDefIndex 8602, 0x060001be..bf
    // The tables are shared static state; every case that writes to one holds a
    // StaticDictionaryLease, which puts back the admitted entries and drops new keys.
    [TestFixture]
    public sealed partial class OriginalHLAutoGeneratedEnumStringTablesTests
    {
        const BindingFlags Statics = BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly;

        // HLUnityUI.Runtime declares the same full name, so resolve this one in HLAutoGenerated.
        static readonly Type CoreExtensions = typeof(BuildFeatures).Assembly.GetType("Hardlight.HardlightEnumExtensions", true);
        static readonly Type CoreExtentions = typeof(Hardlight.HardlightEnumExtentions);
        static readonly Type ErrorExtentions = typeof(global::Enums.EnumExtentions);
        static readonly Type StatsExtentions = typeof(HardlightProject.HardlightEnumExtentions);

        // DummyDll metadata order of the private static (not InitOnly) table fields and
        // the matching GetString parameter types.
        static readonly (Type Owner, string[] Fields, Type[] Enums)[] Shapes =
        {
            (CoreExtensions,
                new[] { "BuildFeaturesEnumToString", "DialogPageIdentifierEnumToString", "GameInputEnumToString",
                    "MenuPageIdentifierEnumToString", "OverlayPageIdentifierEnumToString", "SubPageIdentifierEnumToString",
                    "UIContainerBehaviourEnumToString", "VibrationEventEnumToString", "VibrationTypeEnumToString" },
                new[] { typeof(BuildFeatures), typeof(DialogPageIdentifier), typeof(GameInput), typeof(MenuPageIdentifier),
                    typeof(OverlayPageIdentifier), typeof(SubPageIdentifier), typeof(UIContainerBehaviour),
                    typeof(VibrationEvent), typeof(VibrationType) }),
            (CoreExtentions,
                new[] { "DynamicPageEntryEnumToString", "HLAudioTypesEnumToString" },
                new[] { typeof(DynamicPageEntry), typeof(HLAudioTypes) }),
            (ErrorExtentions, new[] { "ErrorTypesEnumToString" }, new[] { typeof(global::Enums.ErrorTypes) }),
            (StatsExtentions, new[] { "CharacterStatsEnumToString" }, new[] { typeof(CharacterStats) }),
        };

        // TypeDef 0x02000018 attribute rows, in metadata order (ExtensionAttribute omitted):
        // the merged generated partial declarations repeat the two options.
        static readonly Option[] CoreOptions =
        {
            Option.ArrayBoundsChecks, Option.NullChecks, Option.ArrayBoundsChecks, Option.NullChecks,
            Option.ArrayBoundsChecks, Option.NullChecks, Option.ArrayBoundsChecks, Option.NullChecks,
            Option.ArrayBoundsChecks, Option.NullChecks, Option.NullChecks, Option.ArrayBoundsChecks,
            Option.NullChecks, Option.ArrayBoundsChecks, Option.NullChecks, Option.ArrayBoundsChecks,
            Option.ArrayBoundsChecks, Option.NullChecks,
        };

        static Dictionary<T, string> Table<T>(Type owner, string field) =>
            (Dictionary<T, string>)owner.GetField(field, Statics).GetValue(null);

        [Test]
        public void HelpersKeepTheOriginalStaticClassShapes()
        {
            foreach (var (owner, fields, enums) in Shapes)
            {
                Assert.That(owner.Assembly.GetName().Name, Is.EqualTo("HLAutoGenerated"), owner.FullName);
                Assert.That(owner.IsPublic && owner.IsAbstract && owner.IsSealed, Is.True, owner.FullName + " is a static class");
                Assert.That(owner.Attributes.HasFlag(TypeAttributes.BeforeFieldInit), Is.True, owner.FullName);
                Assert.That(owner.IsDefined(typeof(ExtensionAttribute), false), Is.True, owner.FullName);

                FieldInfo[] declared = owner.GetFields(Statics).OrderBy(f => f.MetadataToken).ToArray();
                Assert.That(declared.Select(f => f.Name), Is.EqualTo(fields), owner.FullName);
                for (int i = 0; i < declared.Length; ++i)
                {
                    Assert.That(declared[i].IsPrivate && !declared[i].IsInitOnly, Is.True, declared[i].Name + " is private and mutable");
                    Assert.That(declared[i].FieldType, Is.EqualTo(typeof(Dictionary<,>).MakeGenericType(enums[i], typeof(string))), declared[i].Name);
                }

                MethodInfo[] methods = owner.GetMethods(Statics).OrderBy(m => m.MetadataToken).ToArray();
                Assert.That(methods.Select(m => m.Name), Is.All.EqualTo("GetString"), owner.FullName);
                Assert.That(methods.Select(m => m.GetParameters().Single().ParameterType), Is.EqualTo(enums), owner.FullName);
                foreach (MethodInfo method in methods)
                {
                    Assert.That(method.IsPublic && method.ReturnType == typeof(string), Is.True);
                    Assert.That(method.IsDefined(typeof(ExtensionAttribute), false), Is.True);
                    Assert.That(method.GetParameters().Single().Name, Is.EqualTo("value"));
                }
                Assert.That(owner.TypeInitializer, Is.Not.Null, owner.FullName + " has its .cctor");
            }

            Assert.That(CoreExtensions.GetCustomAttributesData()
                    .Where(a => a.AttributeType == typeof(Il2CppSetOptionAttribute))
                    .Select(a => ((Option)(int)a.ConstructorArguments[0].Value, (bool)a.ConstructorArguments[1].Value)),
                Is.EqualTo(CoreOptions.Select(option => (option, false))));
            foreach (Type owner in new[] { CoreExtentions, ErrorExtentions, StatsExtentions })
                Assert.That(owner.IsDefined(typeof(Il2CppSetOptionAttribute), false), Is.False, owner.FullName);
        }

        // TypeDef 0x02000013 is an ordinary public BeforeFieldInit class (not static) with
        // one Public|Static|InitOnly field. Its .cctor 0x19DD520 allocates the comparer and
        // stores it at static offset 0; .ctor 0x19DD510 only calls Object::.ctor.
        [Test]
        public void ErrorTypesComparerRegistryKeepsItsOriginalShape()
        {
            Type registry = typeof(global::Enums.EnumComparers);
            Assert.That(registry.Assembly.GetName().Name, Is.EqualTo("HLAutoGenerated"));
            Assert.That(registry.IsPublic && !registry.IsAbstract && !registry.IsSealed, Is.True);
            Assert.That(registry.Attributes.HasFlag(TypeAttributes.BeforeFieldInit), Is.True);
            Assert.That(registry.GetCustomAttributesData(), Is.Empty);

            FieldInfo comparer = registry.GetField("ErrorTypesComparer", Statics);
            Assert.That(registry.GetFields(Statics), Is.EqualTo(new[] { comparer }));
            Assert.That(comparer.IsPublic && comparer.IsInitOnly, Is.True);
            Assert.That(comparer.FieldType, Is.EqualTo(typeof(global::Enums.ErrorTypesEqualityComparer)));
            Assert.That(comparer.GetValue(null), Is.TypeOf<global::Enums.ErrorTypesEqualityComparer>());

            ConstructorInfo constructor = registry.GetConstructor(Type.EmptyTypes);
            Assert.That(constructor != null && constructor.IsPublic, Is.True);
            object stored = comparer.GetValue(null);
            Assert.That(new global::Enums.EnumComparers(), Is.Not.Null);
            Assert.That(comparer.GetValue(null), Is.SameAs(stored), "the instance constructor writes no static state");
        }

        // Each .cctor loads the comparer named here from its registry, passes it to the
        // Dictionary(IEqualityComparer) constructor, then calls Add with the raw key
        // immediates and literals listed in NativeRows. The insertion-ordered entry array
        // shows the Add order while no admitted slot has been removed.
        [Test]
        public void TablesUseTheOriginalComparersAndNativeAddOrder()
        {
            CheckTable(CoreExtensions, "BuildFeaturesEnumToString", Hardlight.HardlightEnumComparers.BuildFeaturesComparer, NativeBuildFeatures);
            CheckTable(CoreExtensions, "DialogPageIdentifierEnumToString", Hardlight.HardlightEnumComparers.DialogPageIdentifierComparer, NativeDialogPageIdentifier);
            CheckTable(CoreExtensions, "GameInputEnumToString", Hardlight.HardlightEnumComparers.GameInputComparer, NativeGameInput);
            CheckTable(CoreExtensions, "MenuPageIdentifierEnumToString", Hardlight.HardlightEnumComparers.MenuPageIdentifierComparer, NativeMenuPageIdentifier);
            CheckTable(CoreExtensions, "OverlayPageIdentifierEnumToString", Hardlight.HardlightEnumComparers.OverlayPageIdentifierComparer, NativeOverlayPageIdentifier);
            CheckTable(CoreExtensions, "SubPageIdentifierEnumToString", Hardlight.HardlightEnumComparers.SubPageIdentifierComparer, NativeSubPageIdentifier);
            CheckTable(CoreExtensions, "UIContainerBehaviourEnumToString", Hardlight.HardlightEnumComparers.UIContainerBehaviourComparer, NativeUIContainerBehaviour);
            CheckTable(CoreExtensions, "VibrationEventEnumToString", Hardlight.HardlightEnumComparers.VibrationEventComparer, NativeVibrationEvent);
            CheckTable(CoreExtensions, "VibrationTypeEnumToString", Hardlight.HardlightEnumComparers.VibrationTypeComparer, NativeVibrationType);
            CheckTable(CoreExtentions, "DynamicPageEntryEnumToString", Hardlight.HardlightEnumComparers.DynamicPageEntryComparer, NativeDynamicPageEntry);
            CheckTable(CoreExtentions, "HLAudioTypesEnumToString", Hardlight.HardlightEnumComparers.HLAudioTypesComparer, NativeHLAudioTypes);
            CheckTable(ErrorExtentions, "ErrorTypesEnumToString", global::Enums.EnumComparers.ErrorTypesComparer, NativeErrorTypes);
            CheckTable(StatsExtentions, "CharacterStatsEnumToString", HardlightProject.HardlightEnumComparers.CharacterStatsComparer, NativeCharacterStats);
        }

        static void CheckTable(Type owner, string field, object comparer, (int, string)[] native)
        {
            object table = owner.GetField(field, Statics).GetValue(null);
            Assert.That(table.GetType().GetProperty("Comparer").GetValue(table), Is.SameAs(comparer), field + " comparer");
            var entries = new List<(int, string)>();
            foreach (DictionaryEntry entry in (IDictionary)table) entries.Add((Convert.ToInt32(entry.Key), (string)entry.Value));
            Assert.That(entries, Is.EqualTo(native), field + " entries");
        }

        // GetString (for example 0x19E3A00 and 0x19DD5A0) calls TryGetValue on the live
        // field first, so a hit returns the table's current string, not a fixed name.
        [Test]
        public void GetStringReturnsTheLiveTableEntry()
        {
            Assert.That(GameInput.Up.GetString(), Is.EqualTo("Up"));
            Assert.That(((BuildFeatures)unchecked((int)0xa374e4e9)).GetString(), Is.EqualTo("ASSETBUNDLES"));
            Assert.That(HLAudioTypes.None.GetString(), Is.EqualTo("None"));
            Assert.That(global::Enums.EnumExtentions.GetString((global::Enums.ErrorTypes)0x47c29af8), Is.EqualTo("ACCESS_TOKEN_SYSTEM_MISSING_CONFIG"));
            Assert.That(((CharacterStats)0x48c71542).GetString(), Is.EqualTo("Attack"));

            using (new VerificationFixtureOwnership.StaticDictionaryLease(CoreExtensions, "VibrationTypeEnumToString"))
            using (new VerificationFixtureOwnership.StaticDictionaryLease(StatsExtentions, "CharacterStatsEnumToString"))
            {
                Table<VibrationType>(CoreExtensions, "VibrationTypeEnumToString")[(VibrationType)0x6ce70c9b] = "Replaced";
                Table<CharacterStats>(StatsExtentions, "CharacterStatsEnumToString")[CharacterStats.None] = "Edited";
                Assert.That(((VibrationType)0x6ce70c9b).GetString(), Is.EqualTo("Replaced"));
                Assert.That(CharacterStats.None.GetString(), Is.EqualTo("Edited"));
            }
            Assert.That(((VibrationType)0x6ce70c9b).GetString(), Is.EqualTo("ImpactHeavy"));
            Assert.That(CharacterStats.None.GetString(), Is.EqualTo("None"));
        }

        // A miss boxes the enum for String.Format("0x{0:X}") and stores the result with
        // set_Item after re-reading the field (0x19E3AC4..0x19E3AFE, 0x19DD66D..0x19DD6A9).
        // Enum "X" formatting pads to the eight digits of Int32, so 0x1F is "0x0000001F"
        // and -1 is "0xFFFFFFFF"; the second call returns the cached instance.
        [Test]
        public void MissesFormatAsPaddedUppercaseHexAndAreCached()
        {
            CheckMiss(CoreExtensions, "BuildFeaturesEnumToString", (BuildFeatures v) => v.GetString());
            CheckMiss(CoreExtensions, "DialogPageIdentifierEnumToString", (DialogPageIdentifier v) => v.GetString());
            CheckMiss(CoreExtensions, "GameInputEnumToString", (GameInput v) => v.GetString());
            CheckMiss(CoreExtensions, "MenuPageIdentifierEnumToString", (MenuPageIdentifier v) => v.GetString());
            CheckMiss(CoreExtensions, "OverlayPageIdentifierEnumToString", (OverlayPageIdentifier v) => v.GetString());
            CheckMiss(CoreExtensions, "SubPageIdentifierEnumToString", (SubPageIdentifier v) => v.GetString());
            CheckMiss(CoreExtensions, "UIContainerBehaviourEnumToString", (UIContainerBehaviour v) => v.GetString());
            CheckMiss(CoreExtensions, "VibrationEventEnumToString", (VibrationEvent v) => v.GetString());
            CheckMiss(CoreExtensions, "VibrationTypeEnumToString", (VibrationType v) => v.GetString());
            CheckMiss(CoreExtentions, "DynamicPageEntryEnumToString", (DynamicPageEntry v) => v.GetString());
            CheckMiss(CoreExtentions, "HLAudioTypesEnumToString", (HLAudioTypes v) => v.GetString());
            CheckMiss(ErrorExtentions, "ErrorTypesEnumToString", (global::Enums.ErrorTypes v) => global::Enums.EnumExtentions.GetString(v));
            CheckMiss(StatsExtentions, "CharacterStatsEnumToString", (CharacterStats v) => v.GetString());
        }

        static void CheckMiss<T>(Type owner, string field, Func<T, string> getString) where T : struct, Enum
        {
            var small = (T)Enum.ToObject(typeof(T), 0x1F);
            var negative = (T)Enum.ToObject(typeof(T), -1);
            Dictionary<T, string> table = Table<T>(owner, field);
            Assert.That(table.ContainsKey(small) || table.ContainsKey(negative), Is.False, field + " fixture requires unmapped probes");
            int admitted = table.Count;
            using (new VerificationFixtureOwnership.StaticDictionaryLease(owner, field))
            {
                string first = getString(small);
                Assert.That(first, Is.EqualTo("0x0000001F"), field);
                Assert.That(getString(negative), Is.EqualTo("0xFFFFFFFF"), field);
                Assert.That(table[small], Is.SameAs(first), field + " caches the miss");
                Assert.That(getString(small), Is.SameAs(first), field + " second call hits the cache");
                Assert.That(table.Count, Is.EqualTo(admitted + 2), field);
            }
            Assert.That(table.ContainsKey(small) || table.ContainsKey(negative), Is.False, field + " lease removed the probes");
        }
    }
}
